p=Path('outputs/tomeris_weather_service.py');s=p.read_text(encoding='utf-8').replace("'明日' if '明日' in compact else '今日'", "'明後日' if '明後日' in compact else ('明日' if '明日' in compact else '今日')").replace('(今日|明日)','(明後日|今日|明日)')
s=s.replace("        request=weather_request(question)","        previous_place=getattr(self,'last_weather_place',None)\n        followup=re.fullmatch(r'(今日|明日|明後日)(?:は|の天気は|の天気)?[？?。！!]*',question.strip())\n        request=(previous_place,followup[1]) if followup and previous_place and self.pending_weather else weather_request(question)")
s=s.replace("            if progress: progress", "            self.last_weather_place=place\n            if progress: progress",1);p.write_text(s,encoding='utf-8')
