p=Path('outputs/tomeris_location_guard.py');s=p.read_text(encoding='utf-8-sig').replace("day='明日' if '明日' in text else", "day='明後日' if '明後日' in text else ('明日' if '明日' in text else").replace("self.pending_weather or '今日')", "self.pending_weather or '今日'))")
s=s.replace("        answer=self.location_reply(question)\n        if answer is not None:return answer\n        return super().web_chat", "        answer=self.location_reply(question)\n        if answer is not None:return answer\n        if self.pending_weather and re.fullmatch(r'(今日|明日|明後日)(?:は|の天気は|の天気)?[？?。！!]*',question.strip()):\n            from tomeris_weather_service import DesktopService as WeatherService\n            return WeatherService.web_chat(self,question,model,use_memory,automatic,progress)\n        return super().web_chat",1);p.write_text(s,encoding='utf-8')
